import sys, warnings
sys.path.insert(0, 'C:/Users/agent/work/work/django-14787-panel')
from functools import wraps
from django.utils.decorators import method_decorator

# 1) Issue reproducer: wraps-based decorator over a method
def logger(func):
    @wraps(func)
    def inner(*args, **kwargs):
        return func(*args, **kwargs)
    return inner

class Test:
    @method_decorator(logger)
    def hello_world(self):
        "hello doc"
        return "hello"

assert Test().hello_world() == "hello"
assert Test.hello_world.__name__ == "hello_world"
assert Test.hello_world.__module__ == "__main__"
assert Test.hello_world.__doc__ == "hello doc"
assert Test.hello_world.__wrapped__ is not None

# 2) Attributes added by the decorator are preserved (mirrors test_preserve_attributes)
def myattr_dec(func):
    def wrapper(*args, **kwargs):
        return func(*args, **kwargs)
    wrapper.myattr = True
    return wrapper

class Test2:
    @method_decorator(myattr_dec)
    def method(self):
        "A method"
        pass

assert getattr(Test2().method, 'myattr', False) is True
assert getattr(Test2.method, 'myattr', False) is True
assert Test2.method.__name__ == 'method'
assert Test2.method.__doc__ == 'A method'

# 3) Iterable of decorators + class usage with name=
@method_decorator((myattr_dec, myattr_dec), "method")
class Test3:
    def method(self):
        "A method"
        pass
assert getattr(Test3.method, 'myattr', False) is True
assert Test3.method.__name__ == 'method'

print("ALL CHECKS PASSED")
